import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

"""# Funções

\begin{equation}
R^2 = 1 - \frac{\sum_{i=1}^{n} (y_i - \hat{y}_i)^2}{\sum_{i=1}^{n} (y_i - \bar{y})^2}
\end{equation}

$ X_a = \frac{X_E \cdot (C_{A0} + C_{B0}) }{C_{A0}} $
"""

def fracmolar_para_Xa(xE_array, CA0, CB0):
    """
    Converte fração molar de éster (baseada em A+B+E+W ) em conversão do ácido (Xa).
    """
    xE = np.asarray(xE_array, dtype=float)
    Xa = xE * (CA0 + CB0) / CA0
    return Xa

"""$ X_A = \frac{C_{A0} -C_A}{C_{A0}} $"""

def calcular_conversao(dados_acido):
    """
    Calcula a conversão Xa em relação ao limitante (podendo ser o ácido ou o álcool) e retorna um array [tempo, Xa].

    Parâmetro:
      dados_acido : numpy array de duas colunas [tempo, fração molar ácido]

    Retorno:
      numpy array [tempo, Xa]
    """
    C_A0 = dados_acido[0, 1]  # fração inicial do ácido
    Xa = (C_A0 - dados_acido[:, 1]) / C_A0
    return np.column_stack((dados_acido[:, 0], Xa))

"""$V_t = (\frac{r \cdot BM \cdot MM_{álcool}}{ρ_{álcool}} + \frac{BM \cdot MM_{ácido}}{ρ_{ácido}})$

$C_{ácido} = \frac{BM}{V_t}$


$C_{álcool} = \frac{ r \cdot BM}{V_t}$
"""

def calc_concentracoes_iniciais(r, M_Acido, M_Alcool, rho_Acido, rho_Alcool, BM):
    """
    Calcula as concentrações iniciais (mol/L) do ácido e do álcool
    para uma dada razão molar r = n_alcool/acido.

    Parâmetros:
    r          : razão molar Alcool:Acido
    M_Acido    : massa molar do ácido (g/mol)
    M_Alcool   : massa molar do álcool (g/mol)
    rho_Acido  : densidade do ácido (g/mL)
    rho_Alcool : densidade do álcool (g/mL)
    BM         : base molar (mol de ácido)

    Retorna:
    (C_Alcool, C_Acido) em mol/L
    """
    # Volume total em litros
    V_total_L = ((r * BM * M_Alcool) / rho_Alcool + (BM * M_Acido) / rho_Acido) / 1000.0   # L


    # Concentrações
    C_Alcool = (r * BM)/ V_total_L     #mol/L
    C_Acido = (BM) / V_total_L   # mol/L

    return C_Alcool, C_Acido

"""$ d\frac{C_A}{dt} = - k_d ( C_A \cdot C_B - \frac{C_E*C_W}{K_{eq}}) $"""

def pseudo_estado_estacionario(dados, label, CA0, CB0, Ccat=0.26,guess=0.001):
    """
    Ajusta kd pelo modelo de pseudo-estado estacionário (Keq fixo do equilíbrio) para função de esterificação com proporção 1:1.
    Agora inclui a plotagem do ajuste.
    """

    # Extrai tempo e conversão experimental
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    # Condições iniciais
    C0 = [CA0, CB0, 0.0, 0.0]

    # Modelo cinético
    def model(t, C, kd, Keq):
        CA, CB, CE, CW = C
        ra = float(kd * ((CA * CB) - (CE * CW)/Keq))  # Modelo cinético de segunda ordem considerando, o k com o valor do peso catalítico unidade L/(molmin)
        return np.array([-ra, -ra, ra, ra])

    # -------------------------------
    # Calcular Keq do equilíbrio experimental
    # -------------------------------
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)
    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # -------------------------------
    # Ajuste de kd (Keq fixo)
    # -------------------------------
    def objective_kd(kd):
        sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, Keq), t_eval=t_exp)
        CE_model = sol.y[2]
        return np.sqrt(np.mean((CE_model - CE_exp) ** 2))

    result_kd = minimize(objective_kd, [guess], bounds=[(1e-5, 1)], method='L-BFGS-B')
    kd = result_kd.x[0]
    print(f"kd ajustado = {kd:.6f} L/mol.min")

    # -------------------------------
    # Simulação final


    # -------------------------------
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, Keq), t_eval=t_sim)
    Xa_sim = (CA0 - sol.y[0]) / CA0

    # -------------------------------
    # R² do ajuste
    # -------------------------------
    sol_exp = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, Keq), t_eval=t_exp)
    r2 = r2_score(CE_exp, sol_exp.y[2])

    # -------------------------------
    # Plotagem
    # -------------------------------
    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)

    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd = {kd:.6f}, Keq = {Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    # -------------------------------
    # Resultados
    # -------------------------------
    print(f"\n>>> {label}")
    print(f"CA0  = {CA0:.3f} mol/L")
    print(f"kd   = {kd:.6f} L/mol·min")
    print(f"Keq  = {Keq:.6f}")
    print(f"R²   = {r2:.4f}")

    return t_sim, sol.y[2], Xa_sim, t_exp, CE_exp, Xa_exp, kd, Keq

"""$ d\frac{C_A}{dt} = - k_d \cdot \frac{( C_A \cdot C_B - \frac{C_E*C_W}{K_{eq}})}{(1 + K_w \cdot C_W)} $"""

def pseudo_estado_estacionario_ER(dados, label, CA0, CB0, Ccat=0.26, guess=(0.001, 1.0)):
    """
    Ajusta kd + K_W usando o modelo de Langmuir-Hinshelwood simplificado
    (K_A, K_B, K_E desprezados).

    Modelo cinético:
    ra = (kd * (CA*CB - CE*CW/Keq)) / (1 + K_W*CW)
    """

    # Extrai dados
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]

    # Keq do equilíbrio experimental
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)
    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # Modelo cinético
    def model(t, C, kd, K_W, Keq):
        CA, CB, CE, CW = C
        denom = (1 + K_W*CW)
        ra = kd * ((CA * CB) - (CE * CW)/Keq) / denom
        return np.array([-ra, -ra, ra, ra])

    # Função objetivo
    def objective(params):
        kd, K_W = params
        sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_exp)
        CE_model = sol.y[2]
        return np.sqrt(np.mean((CE_model - CE_exp) ** 2))

    # Otimização
    bounds = [(1e-6, 10), (1e-6, 10)]
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    kd, K_W = result.x

    print(f"Parâmetros ajustados: kd={kd:.6f}, K_W={K_W:.4f}")

    # Simulação final
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd, K_W, Keq), t_eval=t_sim)
    Xa_sim = (CA0 - sol.y[0]) / CA0

    r2 = r2_score(CE_exp, np.interp(t_exp, t_sim, sol.y[2]))

    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd = {kd:.6f}, K_W={K_W:.3f}\nKeq = {Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid()
    plt.tight_layout()
    plt.show()

    return t_sim, sol.y[2], Xa_sim, kd, Keq, K_W, r2

def pseudoestadoestacionario_difusivo(dados, label, CA0, CB0, guess=[0.001, 0.5], bounds=[(1e-6, 10), (0.1, 10)]):
    """
    Ajusta kd (intrínseco) e o módulo de Thiele (phi)
    em um modelo fenomenológico de esterificação heterogênea.

    O efeito difusivo é considerado via fator de efetividade η(ϕ).
    """

    # ==============================
    # 1) Preparação dos dados experimentais
    # ==============================
    t_exp = dados[:, 0]   # tempo experimental
    Xa_exp = dados[:, 1]  # conversão experimental
    CE_exp = Xa_exp * CA0 # concentração de éster (mol/L)

    # Condições iniciais (A, B, E, W)
    C0 = [CA0, CB0, 0.0, 0.0]
    t_span = [0, max(t_exp)]

    # ==============================
    # 2) Definição do fator de efetividade η(ϕ)
    # ==============================
    def fator_efetividade(phi):
        """
        Fator de efetividade para esfera catalítica.
        Aqui usamos a aproximação para reação de ordem 2.
        """
        return (np.sqrt(1 + 4*phi**2) - 1) / (2*phi**2)

    # ==============================
    # 3) Modelo fenomenológico (com difusão)
    # ==============================
    def model(t, C, kd, Keq, phi):
        CA, CB, CE, CW = C

        # taxa intrínseca
        ra_int = kd * (CA*CB - (CE*CW)/Keq)

        # fator de efetividade (difusão interna)
        eta = fator_efetividade(phi)

        # taxa observada = intrínseca * eta
        ra_obs = eta * ra_int

        return np.array([-ra_obs, -ra_obs, ra_obs, ra_obs])

    # ==============================
    # 4) Determinação do Keq pelo equilíbrio experimental
    # ==============================
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)
    print(f"Keq (obtido do equilíbrio experimental) = {Keq:.6f}")

    # ==============================
    # 5) Função objetivo para ajuste
    # ==============================
    def objective(params):
        kd, phi = params
        sol = solve_ivp(model, t_span, C0, args=(kd, Keq, phi), t_eval=t_exp)
        ce_model = sol.y[2]
        rmse = np.sqrt(np.mean((ce_model - CE_exp)**2))
        return rmse

    # ==============================
    # 6) Otimização numérica
    # ==============================
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    best_kd, best_phi = result.x

    # ==============================
    # 7) Simulação final com parâmetros ajustados
    # ==============================
    t_sim = np.linspace(0, max(t_exp), 300)
    sol = solve_ivp(model, t_span, C0, args=(best_kd, Keq, best_phi), t_eval=t_sim)

    # R² do ajuste
    sol_exp = solve_ivp(model, t_span, C0, args=(best_kd, Keq, best_phi), t_eval=t_exp)
    r2 = r2_score(CE_exp, sol_exp.y[2])

    # ==============================
    # 8) Plotagem dos resultados
    # ==============================
    plt.figure(figsize=(10, 6))
    plt.plot(sol.t, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)

    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd = {best_kd:.6f}, phi = {best_phi:.4f}, Keq = {Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    # ==============================
    # 9) Impressão dos resultados
    # ==============================
    eta_final = fator_efetividade(best_phi)
    print(f"\n>>> {label}")
    print(f"kd intrínseco (ajustado): {best_kd:.6f}")
    print(f"Módulo de Thiele (phi): {best_phi:.4f}")
    print(f"Fator de efetividade (eta): {eta_final:.4f}")
    print(f"Keq (fixo do equilíbrio): {Keq:.6f}")
    print(f"R² do ajuste: {r2:.4f}")

    return {
        "kd_intrinseco": best_kd,
        "phi": best_phi,
        "eta": eta_final,
        "Keq": Keq,
        "R2": r2
    }

def pseudo_estado_estacionario_difusivo_livro(dados, label, CA0, CB0,R_particle, De_eff):
    # Parâmetros de Difusão (AJUSTE CONFORME SEU SISTEMA REAL E UNIDADES!)
    R_particle = R_particle  # Exemplo: Raio da partícula do catalisador em metros (m)
    De_eff = De_eff     # Exemplo: Difusividade efetiva em m²/min (ajuste para consistência)

    # Extrai tempo e conversão experimental
    t_exp = dados[:, 0]
    Xa_exp = dados[:, 1]
    CE_exp = Xa_exp * CA0 # Concentração do Éster experimental

    # Condições iniciais para C = [CA, CB, CE, CW]
    C0 = np.array([CA0, CB0, 0.0, 0.0])

    # Modelo cinético de segunda ordem reversível
    def model(t, C, kd_effective, Keq):
        CA, CB, CE, CW = C
        ra = float(kd_effective * ((CA * CB) - (CE * CW)/Keq))
        return np.array([-ra, -ra, ra, ra])

    # Calcular Keq do equilíbrio experimental (da última amostra)
    CE_eq = CE_exp[-1]
    CW_eq = CE_eq # Assumindo estequiometria 1:1 para água
    CA_eq = CA0 - CE_eq
    CB_eq = CB0 - CE_eq
    Keq = (CE_eq * CW_eq) / (CA_eq * CB_eq)
    print(f"Keq (do equilíbrio) = {Keq:.6f}")

    # Função objetivo para ajuste de kd intrínseco
    def objective_kd(kd_intrinsic_guess):
        # Para o módulo de Thiele de 2ª ordem, precisamos de CAs (concentração superficial).
        # Usamos CA0 como uma concentração característica para simplificação.
        # Reveja se esta é a melhor representação para sua reação bimolecular.
        CAs_characteristic = CA0

        # Módulo de Thiele (phi) para reação de SEGUNDA ORDEM (n=2) [1]
        # φn = R * sqrt( ( (n+1)/2 ) * k * CAs^(n-1) / De )
        # Para n=2: φ2 = R * sqrt( (3/2) * k * CAs / De )
        phi = R_particle * np.sqrt((3/2) * abs(kd_intrinsic_guess) * CAs_characteristic / De_eff)

        # Fator de efetividade (eta) - ATENÇÃO: Esta é uma aproximação.
        # A relação funcional exata η(φ) para 2ª ordem não está nas fontes [1, 2].
        if phi < 1e-6:
            eta = 1.0 # Módulo de Thiele pequeno, sem limitações difusionais
        else:
            eta = 1.0 / (1.0 + phi) # Placeholder: Comportamento decrescente de eta com phi

        kd_effective = kd_intrinsic_guess * eta

        # Simula com o kd_effective
        sol = solve_ivp(model, [0, max(t_exp)], C0, args=(kd_effective, Keq), t_eval=t_exp)
        CE_model = sol.y[2] # CE é o terceiro componente (índice 2)
        return np.sqrt(np.mean((CE_model - CE_exp) ** 2)) # RMSE

    # Realiza o ajuste do kd intrínseco
    result_kd = minimize(objective_kd, [guess], bounds=[(1e-10, 1)], method='L-BFGS-B')
    kd_intrinsic_fitted = result_kd.x

    # Cálculos finais de phi, eta e kd_effective para o kd intrínseco ajustado
    CAs_characteristic_final = CA0 # Usando CA0 novamente
    phi_final = R_particle * np.sqrt((3/2) * abs(kd_intrinsic_fitted) * CAs_characteristic_final / De_eff)
    if phi_final < 1e-6:
        eta_final = 1.0
    else:
        eta_final = 1.0 / (1.0 + phi_final)
    kd_effective_final = kd_intrinsic_fitted * eta_final

    print(f"kd intrínseco ajustado = {kd_intrinsic_fitted:.6f} L²/mol²·min")
    print(f"Fator de efetividade (eta) = {eta_final:.4f}")
    print(f"kd efetivo (observado) = {kd_effective_final:.6f} L²/mol²·min")

    # Simulação final com o kd_effective_final
    t_sim = np.linspace(0, max(t_exp), 300)
    sol_sim = solve_ivp(model, [0, max(t_exp)], C0, args=(kd_effective_final, Keq), t_eval=t_sim)
    Xa_sim = (CA0 - sol_sim.y) / CA0 # Conversão de A simulada

    # Cálculo do R² do ajuste
    sol_exp_eval = solve_ivp(model, [0, max(t_exp)], C0, args=(kd_effective_final, Keq), t_eval=t_exp)
    r2 = r2_score(CE_exp, sol_exp_eval.y[2])

    # Plotagem
    plt.figure(figsize=(10, 6))
    plt.plot(t_sim, sol_sim.y[2], label='CE (simulado com difusão)', linewidth=2)
    plt.scatter(t_exp, CE_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'{label}\nkd_intrínseco = {kd_intrinsic_fitted:.6f}, Keq = {Keq:.6f}, eta = {eta_final:.4f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    # Resultados finais impressos
    print(f"\n>>> {label}")
    print(f"CA0  = {CA0:.3f} mol/L")
    print(f"kd intrínseco ajustado = {kd_intrinsic_fitted:.6f} L²/mol²·min")
    print(f"Fator de efetividade (eta) = {eta_final:.4f}")
    print(f"kd efetivo (observado) = {kd_effective_final:.6f} L²/mol²·min")
    print(f"Keq  = {Keq:.6f}")
    print(f"R²   = {r2:.4f}")

    return t_sim, sol_sim.y[2], Xa_sim, t_exp, CE_exp, Xa_exp, kd_intrinsic_fitted, Keq

def ajustar_modelo(data_exp, C0,ce_exp, t_span, t_eval, guess=[0.0001, 1], bounds=[(1e-5, 1), (0.1, 10)]):
    """
    Ajusta parâmetros kd e Keq do modelo de esterificação com proporção 1:1.
    Agora inclui a plotagem do ajuste.
    """

    # ------------------------------
    # Modelo EDO
    # ------------------------------
    def model(t, C, kd, Keq):
        CA, CB, CE, CW = C
        ra = float(kd * ((CA * CB) - (CE * CW)/Keq))     # mesma do pseudoestadoestacionario
        return [-ra, -ra, ra, ra]

    # ------------------------------
    # Função objetivo (RMSE)   Resolução da EDO  !! poderia ser substituido pelo ODES
    # ------------------------------
    def objective(params):
        kd, Keq = params
        sol = solve_ivp(model, t_span, C0, args=(kd, Keq),
                        t_eval=data_exp[:, 0], method='RK45')
        ce_model = sol.y[2]
        rmse = np.sqrt(np.mean((ce_model - ce_exp) ** 2))
        return rmse

    # ------------------------------
    # Otimização     Dados os valores de saida da função de objetivo irei minimizá-los para garantir que esses valores sejam os mínimos globais
    # ------------------------------
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    best_kd, best_Keq = result.x

    # ------------------------------
    # Simulação final
    # ------------------------------
    sol = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq),
                    t_eval=t_eval, method='RK45')

    # Interpolação nos pontos experimentais para calcular R²
    sol_interp = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq),
                           t_eval=data_exp[:, 0], method='RK45')
    ce_sim = sol_interp.y[2]
    r2 = r2_score(ce_exp, ce_sim)

    # ------------------------------
    # Plotagem
    # ------------------------------
    plt.figure(figsize=(10, 6))
    plt.plot(sol.t, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(data_exp[:, 0],ce_exp , color='red', label='CE (experimental)', zorder=5)

    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'Ajuste do Modelo\nkd = {best_kd:.6f}, Keq = {best_Keq:.6f}, R² = {r2:.4f}')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    # ------------------------------
    # Resultados
    # ------------------------------
    print(f"Melhor kd: {best_kd:.6f}")
    print(f"Melhor Keq: {best_Keq:.6f}")
    print(f"Coeficiente de Determinação R²: {r2:.4f}")

    return {
        "kd": best_kd,
        "Keq": best_Keq,
        "R2": r2,
        "t_sim": sol.t,
        "CE_sim": sol.y[2],
        "CE_exp": data_exp[:, 1],
        "tempo_exp": data_exp[:, 0]
    }

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import minimize
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

def ajustar_modelo_ER(data_exp, C0, ce_exp, t_span, t_eval,
                      guess=[0.0001, 1, 0.1], bounds=[(1e-5, 1), (0.1, 10), (0.001, 10)]):
    """
    Ajusta parâmetros kd, Keq e Kw do modelo de Eley-Rideal para a esterificação.
    """

    # ------------------------------
    # Modelo EDO (Eley-Rideal)
    # ------------------------------
    def model(t, C, kd, Keq, Kw):
        CA, CB, CE, CW = C
        # Taxa do modelo Elay-Rideal: adsorção do reagente B no catalisador
        ra = float(kd * ((CA * CB) - (CE * CW)/Keq) / (1 + Kw * CW))
        return [-ra, -ra, ra, ra]

    # ------------------------------
    # Função objetivo (RMSE)
    # ------------------------------
    def objective(params):
        kd, Keq, Kw = params
        sol = solve_ivp(model, t_span, C0, args=(kd, Keq, Kw),
                        t_eval=data_exp[:, 0], method='RK45')
        ce_model = sol.y[2]
        rmse = np.sqrt(np.mean((ce_model - ce_exp) ** 2))
        return rmse

    # ------------------------------
    # Otimização
    # ------------------------------
    result = minimize(objective, guess, bounds=bounds, method='L-BFGS-B')
    best_kd, best_Keq, best_Kw = result.x

    # ------------------------------
    # Simulação final
    # ------------------------------
    sol = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq, best_Kw),
                    t_eval=t_eval, method='RK45')

    # Interpolação nos pontos experimentais para calcular R²
    sol_interp = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq, best_Kw),
                           t_eval=data_exp[:, 0], method='RK45')
    ce_sim = sol_interp.y[2]
    r2 = r2_score(ce_exp, ce_sim)

    # ------------------------------
    # Plotagem
    # ------------------------------
    plt.figure(figsize=(10, 6))
    plt.plot(sol.t, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(data_exp[:, 0], ce_exp, color='red', label='CE (experimental)', zorder=5)

    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f'Ajuste do Modelo Eley-Rideal\nkd={best_kd:.6f}, Keq={best_Keq:.6f}, Kw={best_Kw:.4f}, R²={r2:.4f}')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    # ------------------------------
    # Resultados
    # ------------------------------
    print(f"Melhor kd: {best_kd:.6f}")
    print(f"Melhor Keq: {best_Keq:.6f}")
    print(f"Melhor Kw: {best_Kw:.6f}")
    print(f"Coeficiente de Determinação R²: {r2:.4f}")

    return {
        "kd": best_kd,
        "Keq": best_Keq,
        "Kw": best_Kw,
        "R2": r2,
        "t_sim": sol.t,
        "CE_sim": sol.y[2],
        "CE_exp": data_exp[:, 1],
        "tempo_exp": data_exp[:, 0]
    }

import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import differential_evolution
from sklearn.metrics import r2_score
import matplotlib.pyplot as plt

def ajustar_modelo_global(data_exp, CA0, CB0, t_eval,
                          bounds=[(1e-5, 5), (0.1, 1e4)],  # Limites mais amplos
                          maxiter=1500, popsize=25, seed=None):
    t_exp = data_exp[:, 0]
    Xa_exp = data_exp[:, 1]
    ce_exp = Xa_exp * CA0

    C0 = [CA0, CB0, 0.0, 0.0]
    t_span = (min(t_exp.min(), t_eval.min()), max(t_exp.max(), t_eval.max()))

    def model(t, C, kd, Keq):
        CA, CB, CE, CW = C
        ra = kd * ((CA * CB) - (CE * CW) / Keq)
        return [-ra, -ra, ra, ra]

    def objective(params):
        kd, Keq = params
        try:
            sol = solve_ivp(model, t_span, C0, args=(kd, Keq),
                            t_eval=t_exp, method='RK45',
                            rtol=1e-8, atol=1e-10)
            if sol.status < 0 or np.any(sol.y < -1e-8):
                return np.inf

            ce_model = sol.y[2]
            # Normaliza RMSE pelo valor máximo experimental
            norm_rmse = np.sqrt(np.mean(((ce_model - ce_exp) / (np.max(ce_exp)+1e-8))**2))
            return norm_rmse
        except:
            return np.inf

    result = differential_evolution(objective, bounds=bounds,
                                    maxiter=maxiter, popsize=popsize,
                                    polish=True, seed=seed, disp=True)

    best_kd, best_Keq = result.x

    sol = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq),
                    t_eval=t_eval, method='RK45',
                    rtol=1e-8, atol=1e-10)

    sol_interp = solve_ivp(model, t_span, C0, args=(best_kd, best_Keq),
                           t_eval=t_exp, method='RK45',
                           rtol=1e-8, atol=1e-10)
    ce_sim = sol_interp.y[2]
    r2 = r2_score(ce_exp, ce_sim)

    plt.figure(figsize=(10, 6))
    plt.plot(sol.t, sol.y[2], label='CE (simulado)', linewidth=2)
    plt.scatter(t_exp, ce_exp, color='red', label='CE (experimental)', zorder=5)
    plt.xlabel('Tempo (min)')
    plt.ylabel('Concentração (mol/L)')
    plt.title(f"Ajuste do Modelo\nkd={best_kd:.6f}, Keq={best_Keq:.2f}, R²={r2:.4f}")
    plt.legend()
    plt.grid(alpha=0.3)
    plt.tight_layout()
    plt.show()

    return {
        "kd": best_kd,
        "Keq": best_Keq,
        "R2": r2,
        "t_sim": sol.t,
        "CE_sim": sol.y[2],
        "CE_exp": ce_exp,
        "tempo_exp": t_exp,
        "opt_result": result
    }


